#include "transpose_kernels.cuh"

#include <cuda_runtime.h>

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#define CUDA_CHECK(x) do { cudaError_t e=(x); if(e!=cudaSuccess){ std::ostringstream s; s<<"CUDA error: "<<cudaGetErrorString(e); throw std::runtime_error(s.str()); } } while(0)

namespace {
std::string utcTimestamp() { std::time_t t=std::time(nullptr); std::tm tm{}; gmtime_r(&t,&tm); std::ostringstream s; s<<std::put_time(&tm,"%Y-%m-%dT%H:%M:%SZ"); return s.str(); }
int parseVersion(const std::string& s){ if(s.size()!=2||s[0]!='V'||s[1]<'1'||s[1]>'4') throw std::invalid_argument("version V1..V4 required"); return s[1]-'1'; }
std::vector<float> makeInput(std::size_t n){ std::vector<float> h(n); for(std::size_t i=0;i<n;++i) h[i]=static_cast<float>(static_cast<int>(i%1000003)-500001); return h; }
std::vector<float> expectedOutput(const std::vector<float>& in,std::size_t w,std::size_t h,int version){ if(version==0) return in; std::vector<float> out(in.size()); for(std::size_t y=0;y<h;++y) for(std::size_t x=0;x<w;++x) out[x*h+y]=in[y*w+x]; return out; }
void launch(int version,const float* in,float* out,std::size_t w,std::size_t h){ launchTranspose(static_cast<TransposeVersion>(version),in,out,w,h); CUDA_CHECK(cudaGetLastError()); }

struct Buffers {
  std::size_t w,h,n; std::vector<float> host,expected,actual; float* in=nullptr; float* out=nullptr;
  Buffers(int version,std::size_t width,std::size_t height):w(width),h(height),n(width*height),host(makeInput(n)),expected(expectedOutput(host,width,height,version)),actual(n){
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&in),n*sizeof(float))); CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&out),n*sizeof(float)));
    CUDA_CHECK(cudaMemcpy(in,host.data(),n*sizeof(float),cudaMemcpyHostToDevice));
  }
  bool check(){ CUDA_CHECK(cudaMemcpy(actual.data(),out,n*sizeof(float),cudaMemcpyDeviceToHost)); return std::memcmp(expected.data(),actual.data(),n*sizeof(float))==0; }
  ~Buffers(){ if(in) cudaFree(in); if(out) cudaFree(out); }
};

double eventLaunchMs(int version,Buffers& b,int iterations){ cudaEvent_t a{},z{}; CUDA_CHECK(cudaEventCreate(&a)); CUDA_CHECK(cudaEventCreate(&z)); CUDA_CHECK(cudaEventRecord(a)); for(int i=0;i<iterations;++i) launch(version,b.in,b.out,b.w,b.h); CUDA_CHECK(cudaEventRecord(z)); CUDA_CHECK(cudaEventSynchronize(z)); float total=0; CUDA_CHECK(cudaEventElapsedTime(&total,a,z)); CUDA_CHECK(cudaEventDestroy(a)); CUDA_CHECK(cudaEventDestroy(z)); return total/iterations; }
void ensureSanity(int version,std::size_t w,std::size_t h){ Buffers b(version,w,h); launch(version,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); if(!b.check()) throw std::runtime_error("benchmark correctness sanity failed"); }
void appendCalibration(const std::string& path,std::size_t w,std::size_t h,const std::string& vs,int iterations,double preliminary,int warmupIterations,double estimatedWarmup,double ms){ bool exists=static_cast<bool>(std::ifstream(path)); std::ofstream out(path,std::ios::app); if(!out) throw std::runtime_error("cannot open calibration output"); if(!exists) out<<"timestamp,dimension,version,calibration_iterations,preliminary_kernel_ms,calibration_warmup_iterations,estimated_warmup_ms,calibrated_kernel_ms\n"; out<<utcTimestamp()<<','<<w<<'x'<<h<<','<<vs<<','<<iterations<<','<<std::setprecision(12)<<preliminary<<','<<warmupIterations<<','<<estimatedWarmup<<','<<ms<<'\n'; }
std::string shellQuote(const std::string& s){ std::string r="'"; for(char c:s){ if(c=='\'') r+="'\\''"; else r+=c; } return r+"'"; }
void telemetry(const std::string& script,const std::string& output,const std::string& phase,const std::string& dim,const std::string& vs,int trial){ if(script.empty()||output.empty()) return; std::string cmd="bash "+shellQuote(script)+" "+shellQuote(output)+" "+shellQuote(phase)+" "+shellQuote(dim)+" "+shellQuote(vs)+" "+std::to_string(trial); int rc=std::system(cmd.c_str()); if(rc!=0) std::cerr<<"telemetry command returned "<<rc<<"\n"; }
void writeAdaptiveHeader(const std::string& path){ if(std::ifstream(path)) return; std::ofstream out(path); if(!out) throw std::runtime_error("cannot open raw output"); out<<"timestamp,version,width,height,trial,calibrated_kernel_ms,warmup_iterations,estimated_warmup_ms,measurement_target_ms,measurement_safety_factor,measured_iterations,actual_timed_window_ms,latency_ms,effective_gb_s,correctness_pre\n"; }
void runCalibration(const std::string& vs,std::size_t w,std::size_t h,int warm,int iterations,double warmTarget,int maxWarm,const std::string& output){ int v=parseVersion(vs); Buffers b(v,w,h); launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); if(!b.check()) throw std::runtime_error("calibration correctness sanity failed"); for(int i=0;i<warm;++i) launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); double preliminary=eventLaunchMs(v,b,iterations); int adaptiveWarm=std::max(warm,static_cast<int>(std::ceil(warmTarget/preliminary))); adaptiveWarm=std::min(adaptiveWarm,maxWarm); for(int i=0;i<adaptiveWarm;++i) launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); double ms=eventLaunchMs(v,b,iterations); appendCalibration(output,w,h,vs,iterations,preliminary,adaptiveWarm,adaptiveWarm*preliminary,ms); std::cout<<std::setprecision(12)<<ms<<"\n"; }
void runLegacy(const std::string& vs,std::size_t w,std::size_t h,int warm,int repetitions,int trials,const std::string& output,bool single){ int v=parseVersion(vs); Buffers b(v,w,h); launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); if(!b.check()) throw std::runtime_error("benchmark correctness sanity failed"); if(single){ launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); return; } std::ofstream out(output,std::ios::app); if(!out) throw std::runtime_error("cannot open legacy output"); for(int trial=1;trial<=trials;++trial){ for(int i=0;i<warm;++i) launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); double latency=eventLaunchMs(v,b,repetitions); double gb=(2.0*static_cast<double>(b.n)*sizeof(float))/(latency*1.0e6); out<<vs<<','<<w<<','<<h<<','<<trial<<','<<warm<<','<<repetitions<<','<<std::setprecision(10)<<latency<<','<<gb<<"\n"; } }
void runAdaptive(const std::string& vs,std::size_t w,std::size_t h,int trial,double calibrated,double warmTarget,double measureTarget,double safetyFactor,int minWarm,int maxWarm,int minMeasure,int maxMeasure,const std::string& output,const std::string& telemetryScript,const std::string& telemetryOutput){ if(calibrated<=0) throw std::invalid_argument("calibrated latency must be positive"); int v=parseVersion(vs); Buffers b(v,w,h); launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); if(!b.check()) throw std::runtime_error("benchmark correctness sanity failed"); int warm=std::max(minWarm,static_cast<int>(std::ceil(warmTarget/calibrated))); warm=std::min(warm,maxWarm); int measure=std::max(minMeasure,static_cast<int>(std::ceil(measureTarget*safetyFactor/calibrated))); measure=std::min(measure,maxMeasure); for(int i=0;i<warm;++i) launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaDeviceSynchronize()); telemetry(telemetryScript,telemetryOutput,"pre",std::to_string(w)+"x"+std::to_string(h),vs,trial); cudaEvent_t a{},z{}; CUDA_CHECK(cudaEventCreate(&a)); CUDA_CHECK(cudaEventCreate(&z)); CUDA_CHECK(cudaEventRecord(a)); for(int i=0;i<measure;++i) launch(v,b.in,b.out,w,h); CUDA_CHECK(cudaEventRecord(z)); CUDA_CHECK(cudaEventSynchronize(z)); float total=0; CUDA_CHECK(cudaEventElapsedTime(&total,a,z)); CUDA_CHECK(cudaEventDestroy(a)); CUDA_CHECK(cudaEventDestroy(z)); telemetry(telemetryScript,telemetryOutput,"post",std::to_string(w)+"x"+std::to_string(h),vs,trial); double actual=total; double latency=actual/measure; double gb=(2.0*static_cast<double>(b.n)*sizeof(float))/(latency*1.0e6); writeAdaptiveHeader(output); std::ofstream out(output,std::ios::app); out<<utcTimestamp()<<','<<vs<<','<<w<<','<<h<<','<<trial<<','<<std::setprecision(12)<<calibrated<<','<<warm<<','<<warm*calibrated<<','<<measureTarget<<','<<safetyFactor<<','<<measure<<','<<actual<<','<<latency<<','<<gb<<",PASS\n"; }
}

int main(int argc,char**argv){ try { std::string vs,raw,calibration,telemetryScript,telemetryOutput,legacyOutput; std::size_t w=0,h=0; int warm=20,iterations=50,trial=0,minWarm=20,maxWarm=20000,minMeasure=100,maxMeasure=10000,repetitions=100,trials=5; double calibrated=0,warmTarget=1000,measureTarget=500,safetyFactor=2.0; bool calibrate=false,adaptive=false,sanity=false,single=false; for(int i=1;i<argc;++i){std::string a=argv[i]; if(a=="--version"&&i+1<argc)vs=argv[++i]; else if(a=="--width"&&i+1<argc)w=std::stoull(argv[++i]); else if(a=="--height"&&i+1<argc)h=std::stoull(argv[++i]); else if(a=="--calibrate")calibrate=true; else if(a=="--adaptive")adaptive=true; else if(a=="--sanity-only")sanity=true; else if(a=="--single")single=true; else if(a=="--warmup"&&i+1<argc)warm=std::stoi(argv[++i]); else if(a=="--repetitions"&&i+1<argc)repetitions=std::stoi(argv[++i]); else if(a=="--trials"&&i+1<argc)trials=std::stoi(argv[++i]); else if(a=="--output"&&i+1<argc)legacyOutput=argv[++i]; else if(a=="--calibration-warmup"&&i+1<argc)warm=std::stoi(argv[++i]); else if(a=="--calibration-iterations"&&i+1<argc)iterations=std::stoi(argv[++i]); else if(a=="--calibrated-ms"&&i+1<argc)calibrated=std::stod(argv[++i]); else if(a=="--warmup-target-ms"&&i+1<argc)warmTarget=std::stod(argv[++i]); else if(a=="--measurement-target-ms"&&i+1<argc)measureTarget=std::stod(argv[++i]); else if(a=="--measurement-safety-factor"&&i+1<argc)safetyFactor=std::stod(argv[++i]); else if(a=="--min-warmup"&&i+1<argc)minWarm=std::stoi(argv[++i]); else if(a=="--max-warmup"&&i+1<argc)maxWarm=std::stoi(argv[++i]); else if(a=="--min-measurement"&&i+1<argc)minMeasure=std::stoi(argv[++i]); else if(a=="--max-measurement"&&i+1<argc)maxMeasure=std::stoi(argv[++i]); else if(a=="--trial"&&i+1<argc)trial=std::stoi(argv[++i]); else if(a=="--raw"&&i+1<argc)raw=argv[++i]; else if(a=="--calibration-output"&&i+1<argc)calibration=argv[++i]; else if(a=="--telemetry-script"&&i+1<argc)telemetryScript=argv[++i]; else if(a=="--telemetry-output"&&i+1<argc)telemetryOutput=argv[++i]; else if(a=="--device-info"){cudaDeviceProp p{}; CUDA_CHECK(cudaGetDeviceProperties(&p,0)); std::cout<<p.name<<" cc "<<p.major<<'.'<<p.minor<<"\n"; return 0;} }
  if(vs.empty()||!w||!h) throw std::invalid_argument("--version --width --height required"); if(calibrate){ if(calibration.empty()) throw std::invalid_argument("--calibration-output required"); runCalibration(vs,w,h,warm,iterations,warmTarget,maxWarm,calibration); return 0; } if(sanity){ ensureSanity(parseVersion(vs),w,h); std::cout<<vs<<" PASS\n"; return 0; } if(adaptive){ if(trial<=0||raw.empty()) throw std::invalid_argument("adaptive requires --trial and --raw"); runAdaptive(vs,w,h,trial,calibrated,warmTarget,measureTarget,safetyFactor,minWarm,maxWarm,minMeasure,maxMeasure,raw,telemetryScript,telemetryOutput); return 0; } if(single||!legacyOutput.empty()){ if(!single&&legacyOutput.empty()) throw std::invalid_argument("--output required"); runLegacy(vs,w,h,warm,repetitions,trials,legacyOutput,single); return 0; } throw std::invalid_argument("use --calibrate, --adaptive, --sanity-only or legacy --output"); } catch(const std::exception&e){ std::cerr<<e.what()<<"\n"; return 1; } }
